holder=`"Adicione observacoes importantes sobre este lancamento...`"></textarea></div><button class=`"lanc-btn-primary`" onclick=`"window.salvarMapa()`" style=`"flex-shrink:0;`"><i class=`"fas fa-save`"></i> Salvar Mapa</button></div>`r`n                                </div>`r`n                              </div>`r`n                              <div class=`"lanc-table-area`">`r`n                                <div class=`"lanc-table-header`"><h3 class=`"lanc-table-title`" id=`"lanc-table-heading`">Medicoes Salvas em 2026</h3><div class=`"lanc-table-controls`"><button class=`"lanc-btn-secondary`" onclick=`"window.lancImprimirTabela()`"><i class=`"fas fa-print`"></i> Imprimir Tabela</button><select class=`"lanc-filter-select`" id=`"lanc-filtro-ano`" onchange=`"window.lancFiltrarMedicoes()`"><option value=`"2026`" selected>2026</option><option value=`"2025`">2025</option><option value=`"2024`">2024</option></select><select class=`"lanc-filter-select`" id=`"lanc-filtro-mes`" onchange=`"window.lancFiltrarMedicoes()`"><option value=`"`">Todos os Meses</option><option value=`"1`">Janeiro</option><option value=`"2`">Fevereiro</option><option value=`"3`">Marco</option><option value=`"4`">Abril</option><option value=`"5`">Maio</option><option value=`"6`">Junho</option><option value=`"7`">Julho</option><option value=`"8`">Agosto</option><option value=`"9`">Setembro</option><option value=`"10`">Outubro</option><option value=`"11`">Novembro</option><option value=`"12`">Dezembro</option></select><select class=`"lanc-filter-select`" id=`"lanc-filtro-status`" onchange=`"window.lancFiltrarMedicoes()`"><option value=`"`">Todos os Status</option><option value=`"Pendente`">Pendente</option><option value=`"Em Processo`">Em Processo</option><option value=`"Pago`">Pago</option></select></div></div>`r`n                                <div class=`"lanc-table-wrap`"><table class=`"lanc-table`"><thead><tr><th>Competencia</th><th>Emissao</th><th>N.o NF</th><th>N.o Empenho</th><th>N.o Proc.