        $content = $content.Replace($marker, $lancContent)
        Write-Host "Step 2 OK: tab content injected."
    } else {
        Write-Host "Step 2 FAILED: marker still not found. Trying alternative..."
        # Try without the trailing spaces on the blank line
        $marker2 = "</div>`r`n                            `r`n                        </div>`r`n                    </div>"
        if ($content.Contains($marker2)) {
            Write-Host "Alternative marker found!"
        } else {
            Write-Host "Alternative also not found."
            # Get exact chars around relatorio-conteudo
            $idx = $content.IndexOf("relatorio-conteudo")
            if ($idx -ge 0) {
                $raw = $content.Substring($idx, 200)
                Write-Host "Raw bytes after relatorio-conteudo:"
                for ($i=0; $i -lt $raw.Length; $i++) {
                    $b = [int][char]$raw[$i]
                    if ($b -lt 32) { Write-Host -NoNewline "[$b]" } else { Write-Host -NoNewline $raw[$i] }
                }
                Write-Host ""
            }
        }
